/// <summary>
/// Bitflags controlling instance debugging and validation behavior.
/// <para/>
/// These are not part of the WebGPU standard.
/// <para/>
/// Pass in the <c>flags</c> field of <c>WGPUInstanceExtras</c>.
/// <para/>
/// <c>WGPUInstanceFlag</c> from <c>wgpu.h</c>.
/// </summary>
[Flags]
public enum WGPUInstanceFlag : ulong
{
    /// <summary>
    /// No flags set.
    /// </summary>
    Empty = 0x00000000,
    /// <summary>
    /// Generate debug information in shaders and objects.
    /// <para/>
    /// When using <c>WGPUInstanceFlag_WithEnv</c>, takes value from the
    /// <c>WGPU_DEBUG</c> environment variable.
    /// </summary>
    Debug = 1 << 0,
    /// <summary>
    /// Enable validation in the backend API, if possible:
    /// <para/>
    /// - On the DX12 backend, this calls <c>ID3D12Debug::EnableDebugLayer.</c>
    /// - On the Vulkan backend, this enables the Vulkan Validation Layers.
    /// - On the GLES backend (Windows), this enables debug output.
    /// - On the GLES backend (non-Windows), this calls <c>eglDebugMessageControlKHR.</c>
    /// <para/>
    /// When using <c>WGPUInstanceFlag_WithEnv</c>, takes value from the
    /// <c>WGPU_VALIDATION</c> environment variable.
    /// </summary>
    Validation = 1 << 1,
    /// <summary>
    /// Don't pass labels to the backend API (wgpu-hal).
    /// <para/>
    /// When using <c>WGPUInstanceFlag_WithEnv</c>, takes value from the
    /// <c>WGPU_DISCARD_HAL_LABELS</c> environment variable.
    /// </summary>
    DiscardHalLabels = 1 << 2,
    /// <summary>
    /// Whether wgpu should expose adapters that run on top of non-compliant
    /// adapters.
    /// <para/>
    /// Turning this on might mean that some of the functionality provided by the
    /// wgpu adapter/device is not working or broken. This mainly applies to a
    /// Vulkan driver's compliance version. If the major compliance version is 0,
    /// then the driver is ignored unless this flag is set.
    /// <para/>
    /// When using <c>WGPUInstanceFlag_WithEnv</c>, takes value from the
    /// <c>WGPU_ALLOW_UNDERLYING_NONCOMPLIANT_ADAPTER</c> environment variable.
    /// </summary>
    AllowUnderlyingNoncompliantAdapter = 1 << 3,
    /// <summary>
    /// Enable GPU-based validation. Implies <c>WGPUInstanceFlag_Validation</c>.
    /// Currently only changes behavior on the DX12 and Vulkan backends.
    /// <para/>
    /// - D3D12: Called "GPU-based validation" (GBV).
    /// - Vulkan: Called "GPU-Assisted Validation" via VK_LAYER_KHRONOS_validation.
    /// <para/>
    /// When using <c>WGPUInstanceFlag_WithEnv</c>, takes value from the
    /// <c>WGPU_GPU_BASED_VALIDATION</c> environment variable.
    /// </summary>
    GPUBasedValidation = 1 << 4,
    /// <summary>
    /// Validate indirect buffer content prior to issuing indirect draws/dispatches.
    /// <para/>
    /// This validation will transform indirect calls into no-ops if they are not
    /// valid. For example, <c>dispatch_workgroups_indirect</c> arguments must be less
    /// than the <c>max_compute_workgroups_per_dimension</c> device limit.
    /// <para/>
    /// When using <c>WGPUInstanceFlag_WithEnv</c>, takes value from the
    /// <c>WGPU_VALIDATION_INDIRECT_CALL</c> environment variable.
    /// </summary>
    ValidationIndirectCall = 1 << 5,
    /// <summary>
    /// Enable automatic timestamp normalization. When enabled,
    /// <c>wgpuCommandEncoderResolveQuerySet</c> will automatically normalize timestamps
    /// to nanoseconds instead of returning raw timestamp values.
    /// <para/>
    /// This introduces a compute shader into the resolution of query sets. When
    /// enabled, the timestamp period returned by <c>wgpuQueueGetTimestampPeriod</c>
    /// will always be <c>1.0.</c>
    /// </summary>
    AutomaticTimestampNormalization = 1 << 6,
    /// <summary>
    /// Restrict the available feature set to the one defined by the WebGPU
    /// specification. Adapters that can't fully satisfy the WebGPU v1 spec are
    /// excluded, and spec-forbidden behaviour (e.g. <c>WGPULoadOp_DontCare</c>) is
    /// rejected.
    /// <para/>
    /// When using <c>WGPUInstanceFlag_WithEnv</c>, takes value from the
    /// <c>WGPU_STRICT_WEBGPU_COMPLIANCE</c> environment variable.
    /// </summary>
    StrictWebgpuCompliance = 1 << 7,
    /// <summary>
    /// Use the default flags for the current build configuration.
    /// In debug builds, this typically enables <c>WGPUInstanceFlag_Debug</c> and
    /// <c>WGPUInstanceFlag_Validation</c>.
    /// </summary>
    Default = 1 << 24,
    /// <summary>
    /// Convenience alias that enables <c>WGPUInstanceFlag_Debug</c> and
    /// <c>WGPUInstanceFlag_Validation</c>.
    /// </summary>
    Debugging = 1 << 25,
    /// <summary>
    /// Convenience alias that enables <c>WGPUInstanceFlag_Debug</c>,
    /// <c>WGPUInstanceFlag_Validation</c>, and
    /// <c>WGPUInstanceFlag_GPUBasedValidation</c>.
    /// </summary>
    AdvancedDebugging = 1 << 26,
    /// <summary>
    /// Modify the flags based on environment variables. Flags with environment
    /// variable support (e.g. <c>WGPU_DEBUG</c>, <c>WGPU_VALIDATION</c>) will be read
    /// from the process environment and applied on top of the explicitly set flags.
    /// </summary>
    WithEnv = 1 << 27,
}

